import { test, expect } from './fixtures';

test('shows tooltip when hovering the function button', async ({ page }) => {
  await page.goto('/');

  await page.getByRole('button', { name: 'Create test file' }).click();

  await page.getByRole('link', { name: 'Accounts' }).first().click();
  await page.getByRole('link', { name: 'Bank of America' }).first().click();

  await page.getByRole('button', { name: 'Add Transaction' }).click();

  const functionButton = page.getByRole('button', { name: /function|fx/i }).first();
  await expect(functionButton).toBeVisible();
  await functionButton.hover();

  const tooltip = page.locator('functiontooltip');
  await expect(tooltip).toBeVisible();
  await expect(tooltip).not.toBeEmpty();
});

import { test, expect } from './fixtures';

test('actual_desktop smoke test: navigate to home and cart', async ({ page }) => {
  // Go to the home page
  await page.goto('/#/');

  // Expect the main content area to be visible (adjust selector as needed)
  await expect(page.locator('main, #root, .app')).toBeVisible();

  // Navigate to the cart page using relative navigation
  await page.goto('/#/cart');

  // Expect the cart heading to be present
  await expect(page.getByRole('heading', { name: /cart/i })).toBeVisible();
});
